const newItems = $('Check Scraper Errors').all(); // Clean items
// Safely get reference data directly from node execution
// Note: Reference nodes ran sequentially, so data MUST be there
const existingNews = $('Get Existing News').all(); 
const cachedNews = $('Get Cache').all();

const existingUrls = new Set();
if (existingNews && existingNews.length) {
  existingNews.forEach(i => { if(i.json.url) existingUrls.add(i.json.url); });
}

const cachedMap = new Map();
if (cachedNews && cachedNews.length) {
  cachedNews.forEach(i => {
    if(i.json.url) cachedMap.set(i.json.url, i.json);
  });
}

const toProcess = [];

for (const item of newItems) {
  const url = item.json.link || item.json.url;

  // Deduplicate
  if (existingUrls.has(url)) continue;

  // Cache Check
  if (cachedMap.has(url)) {
      const cached = cachedMap.get(url);
      item.json = {
          ...item.json,
          ...JSON.parse(cached.result_json || '{}'),
          is_cached: true
      };
  } else {
      item.json.is_cached = false;
      const raw_text = item.json.content || item.json.description || item.json.summary || "";

      // CLEAN NOISE: Truncate trash
      let clean_text = raw_text;
      const markers = ["Most Popular Articles", "Latest comments", "Trade With A Regulated Broker", "View all comments", "More News", "Market Movers"];
      for (const m of markers) {
          const idx = clean_text.indexOf(m);
          if (idx > 200) clean_text = clean_text.substring(0, idx);
      }

      // FIX: Escape backticks for template string safety
      clean_text = clean_text.replace(/`/g, "\\`");

      // AGENT PROMPT: FINANCIAL ANALYST (READ-INTERPRET-GENERATE)
      item.json.prompt_para_api = `### Role:\nYou are a Senior Financial Analyst at a top Wall Street firm.\n\n### Task:\nAnalyze the provided news content and output a STRICT JSON object.\n\n### EXECUTION STEPS (INTERNAL PROCESS):\n1. **READ**: Read the entire news content carefully.\n2. **INTERPRET**: mentally evaluate the financial implications, identifying key catalysts, risks, and market sentiment.\n3. **GENERATE**: Populate the JSON fields based STRICTLY on your interpretation. Do not hallucinate data not present or implied by the text.\n\n### FIELD DEFINITIONS (CRITICAL):\n1. **market_impact**: Explain specifically HOW this affects the asset price or sector. Don't just say \"it affects\". Mention volatility, trend reversal, or volume spikes. (Max 2 sentences, Spanish).\n2. **sentiment**: The direct market mood implied by the text. BULLISH (Optimistic/Uptrend), BEARISH (Pessimistic/Downtrend), NEUTRAL (Ambiguous/Sideways).\n3. **action**: Your professional recommendation. BUY (Positive catalyst), SELL (Negative catalyst), HOLD (Uncertainty/Wait), DISCARD (Irrelevant/Spam).\n4. **investment_advice**: Concrete reasoning connecting the news to the Action. Why buy/sell? (Spanish).\n5. **category**: High-level domain (MERCADOS, MACRO, CRIPTO, CORPORATIVO, DIVISAS, REGULACIÓN, OTROS).\n6. **asset_class**: Specific asset type (ACCIONES, CRIPTOMONEDAS, FOREX, MATERIAS PRIMAS, ÍNDICES, RENTA FIJA, MULTIASTET).\n7. **tags**: List of 2-5 relevant keywords (tickers, entities, or concepts).\n\n### CRITICAL INSTRUCTIONS:\n1. **RELEVANCE CHECK**: If the content is strictly legal/procedural (like Form 8-K), spam, or has NO financial market relevance, set \"action\" to \"DISCARD\" and \"market_impact\" to \"IRRELEVANT\".\n2. **NO MARKDOWN**: Output raw JSON only.\n3. **LANGUAGE**: Output values in SPANISH where requested.\n\n### Content:\n${clean_text}\n\n### Output Schema:\n{\n  \"title\": \"Spanish Title (Max 15 words)\",\n  \"summary\": \"Concise summary in Spanish\",\n  \"market_impact\": \"(MANDATORY) Analysis in Spanish based on definition above.\",\n  \"sentiment\": \"BULLISH | BEARISH | NEUTRAL\",\n  \"risk_level\": \"LOW | MEDIUM | HIGH\",\n  \"action\": \"BUY | SELL | HOLD | DISCARD\",\n  \"category\": \"...\",\n  \"asset_class\": \"...\",\n  \"tags\": [\"...\", \"...\"],\n  \"investment_advice\": {\n    \"rating\": \"Buy/Hold/Sell\",\n    \"reasoning\": \"Explanation in Spanish\"\n  },\n  \"image_prompt\": \"Futuristic financial illustration...\"\n}`;

      // ATTACH METADATA FOR PRESERVATION
      item.json.metadata_para_api = {
          url: url,
          source_content: raw_text,
          published_date: item.json.isoDate || item.json.pubDate || new Date().toISOString()
      };
  }
  toProcess.push(item);
}

return toProcess;

// AGGREGATOR NODE: Combine all items in the batch into a SINGLE request payload
// This prevents the HTTP Request node from executing multiple times in parallel

const noticias = items.map(item => ({
    text: item.json.prompt_para_api,
    metadata: item.json.metadata_para_api
}));

return [{
    json: {
        payload: {
            noticias: noticias,
            callback_url: "http://34.9.244.104:5678/webhook/webhook-callback"
        }
    }
}];

// Prepare content for Cache Saving
for (const item of items) {
  item.json.result_json = JSON.stringify(item.json);
}
return items;

for (const item of items) {
  let llmResult = {};

  // FIX: Handle 'result_json' string from Cache or Previous Node
  if (item.json.result_json) {
      try {
          const parsed = typeof item.json.result_json === 'string' ? JSON.parse(item.json.result_json) : item.json.result_json;
          // Unwrap nested 'body.results'
          if (parsed['body.results']) {
              llmResult = parsed['body.results'];
          } else if (parsed.body && parsed.body.results) {
              llmResult = parsed.body.results;
          } else {
              llmResult = parsed;
          }
      } catch (e) {
          console.log('Error parsing result_json', e);
      }
  } else if (item.json.result) {
      // Fallback for legacy format
       llmResult = typeof item.json.result === 'string' ? JSON.parse(item.json.result) : item.json.result;
  }

  const subjectPrompt = item.json.image_prompt || (llmResult ? llmResult.image_prompt : '') || 'Financial graph';

  // Use existing image_url from microservice if available
  let imageUrl = llmResult.image_url || item.json.image_url || item.json.generated_image_url || '';
  let tempId = item.json.temp_id || 'news_' + Math.floor(Math.random()*100000);

  if (!imageUrl || !imageUrl.includes('storage.googleapis.com')) {
      const style = "flat vector art, modern corporate memphis style, financial technology aesthetic, minimalist, clean lines, vibrant blue and white colors, high quality";
      const fullPrompt = `${subjectPrompt}, ${style}`;
      const encodedPrompt = encodeURIComponent(fullPrompt);
      const seed = Math.floor(Math.random() * 10000);
      imageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=800&height=600&seed=${seed}`;
  }

  item.json = {
    ...item.json,
    ...llmResult,
    generated_image_url: imageUrl,
    temp_id: tempId
  };
}
return items;

const validItems = [];
const seenIds = new Set();

for (const item of items) {
   let data = item.json;

   if (data['body.results']) {
       if (data['body.results'].result_json && typeof data['body.results'].result_json === 'string') {
           try {
               const parsed = JSON.parse(data['body.results'].result_json);
               data = { ...data, ...(parsed['body.results'] || parsed) };
           } catch(e) { console.log('Error parsing nested result_json', e); }
       } else {
           data = { ...data, ...data['body.results'] };
       }
   }

   if (data.result_json && typeof data.result_json === 'string') {
       try {
           const parsed = JSON.parse(data.result_json);
           data = { ...data, ...(parsed['body.results'] || parsed) };
       } catch(e) { console.log('Error parsing root result_json', e); }
   }

   const bucket = 'alphaseeker-assets';
   let imageUrl = data.image_url || item.json.generated_image_url || data.generated_image_url || '';

   if (item.json.name) {
       imageUrl = `https://storage.googleapis.com/${bucket}/${item.json.name}`;
   } else if (item.json.temp_id && !imageUrl.includes('storage.googleapis.com')) {
       imageUrl = `https://storage.googleapis.com/${bucket}/news-images/${item.json.temp_id}.jpg`;
   }

   if (data.action === 'DISCARD' || data.market_impact === 'IRRELEVANT') {
       continue;
   }

   const generatedId = data.url ? data.url.replace(/[^a-zA-Z0-9]/g, '_').substring(0, 100) : 'news_' + Math.floor(Math.random() * 1000);

   if (seenIds.has(generatedId)) {
       console.log('Deduplicación n8n: Saltando noticia duplicada con ID:', generatedId);
       continue;
   }
   seenIds.add(generatedId);

   const normalized = {
       id: generatedId,
       title: data.title || 'Market News',
       content_summary: data.summary || data.content_summary || '',
       content: data.source_content || data.content || '', 
       published_date: new Date().toISOString(),
       url: data.url || '',
       source: 'n8n',
       investment_advice: data.investment_advice || { rating: 'Hold', reasoning: 'Insufficient data' },
       market_impact: data.market_impact || '',
       risk_level: data.risk_level || 'MEDIUM',
       sentiment: data.sentiment || 'NEUTRAL',
       analysis: data.analysis || data.market_impact || '', 
       action: data.action || 'HOLD',
       category: data.category || 'MERCADOS',
       asset_class: data.asset_class || 'ACCIONES',
       tags: Array.isArray(data.tags) ? data.tags : [],
       image_url: imageUrl
   };

   if (!normalized.market_impact) {
       continue;
   }

   item.json = normalized;
   validItems.push(item);
}

return validItems;

